下面的代码是一个作曲家答题器。输入答案后点击提交，{{term:JS}} 判断你的答案是否正确：

```js
// 获取输入框里用户写的内容
let answer = document.querySelector("#answer").value;

// if/else：条件判断——"如果...就...否则..."
if (answer === "肖邦") {                              // === 比较是否相等
  display.textContent = "✓ 回答正确！";              // 条件成立走这里
} else {
  display.textContent = "✗ 再想想？提示：他是波兰人"; // 条件不成立走这里
}
```切换到 {{term:JS}} {{term:标签}}页，看 {{term:submit}} 按钮的点击{{term:事件}}中完整的 {{term:if/else}} 逻辑。

starter.css:
h1 {
  text-align: center;
  color: #8B2E2E;
}
.quiz-box {
  background: #FFFAF2;
  border: 2px solid #D4C5A9;
  border-radius: 12px;
  padding: 32px;
  max-width: 400px;
  margin: 20px auto;
  text-align: center;
}
.quiz-question {
  font-size: 18px;
  color: #3D2B1F;
  margin-bottom: 16px;
}
#answer {
  width: 100%;
  padding: 10px 14px;
  border: 1px solid #D4C5A9;
  border-radius: 6px;
  font-size: 16px;
  font-family: inherit;
  text-align: center;
}
#submitBtn {
  margin-top: 12px;
  padding: 10px 32px;
  background: #8B2E2E;
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 16px;
  cursor: pointer;
}
#submitBtn:hover {
  background: #C94545;
}
#result {
  margin-top: 16px;
  font-size: 18px;
  font-weight: 600;
  min-height: 28px;
}

starter.js:
let btn = document.querySelector("#submitBtn");
let result = document.querySelector("#result");
btn.addEventListener("click", function() {
  let answer = document.querySelector("#answer").value;
  if (answer === "肖邦") {
    result.style.color = "#5B8C5A";
    result.textContent = "✓ 回答正确！肖邦确实是钢琴诗人。";
  } else if (answer === "") {
    result.style.color = "#C9A96E";
    result.textContent = "请先输入一个名字哦 ~";
  } else {
    result.style.color = "#8B2E2E";
    result.textContent = "✗ 再想想？提示：他是波兰人，写了很多夜曲。";
  }
});
